fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Vec<Vec<i8>> {
    // Extract the number of rows and columns from the shape
    let r = shape[0] as usize;
    let c = shape[1] as usize;
    
    // Create a new matrix with the specified shape
    let mut matrix = vec![vec![0; c]; r];

    // Check if the length of the array matches the number of rows
    if a.len() == r {
        for i in 0..r {
            matrix[i] = a.clone(); // Fill each row with the array
        }
    } else {
        // Otherwise, the length of the array must match the number of columns
        for i in 0..r {
            for j in 0..c {
                matrix[i][j] = a[j]; // Fill each column with the array
            }
        }
    }

    matrix
}